#include <iostream>
#include <string>

class GradeBook {
public:
    explicit GradeBook(std::string name) {
        setCourseName(name);
    }

    void setCourseName(std::string name) {
        if (name.size() <= 25) {
            courseName = name;
        } else {
            courseName = name.substr(0, 25);
            std::cout << "Name \"" << name << "\" exceeds maximum length (25).\n"
                         "Limiting courseName to first 25 characters.\n" << std::endl;
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!" << std::endl;
    }

private:
    std::string courseName;
};

int main() {
    GradeBook gradeBook1("CS101 Introduction to Programming in C++");
    GradeBook gradeBook2("CS102 C++ Data Structures");

    std::cout << "gradeBook1's initial course name is: "
              << gradeBook1.getCourseName()
              << "\ngradeBook2's initial course name is: "
              << gradeBook2.getCourseName() << std::endl;

    gradeBook1.setCourseName("CS101 C++ Programming");

    std::cout << "\ngradeBook1's course name is: "
              << gradeBook1.getCourseName()
              << "\ngradeBook2's course name is: "
              << gradeBook2.getCourseName() << std::endl;

    return 0;
}

#include <iostream>
#include <string>

// Clean design demonstrating Chapter 3 principles
class Course {
public:
    // Explicit constructor to prevent implicit conversion
    explicit Course(std::string name) {
        setName(name);
    }

    // Validator set function maintaining consistent state
    void setName(std::string name) {
        if (name.empty()) {
            courseName = "Untitled Course";
        } else if (name.size() > 20) {
            courseName = name.substr(0, 20);
        } else {
            courseName = name;
        }
    }

    // Const member function guarantees no modification to state
    std::string getName() const {
        return courseName;
    }

private:
    std::string courseName;
};

int main() {
    Course c1("Data Structures and Algorithms");
    Course c2("");

    std::cout << "c1 name: " << c1.getName() << std::endl;
    std::cout << "c2 name: " << c2.getName() << std::endl;

    c1.setName("C++ Modern Core");
    std::cout << "c1 updated name: " << c1.getName() << std::endl;

    return 0;
}
